export type ProfileKey = keyof typeof profileTranslationRows;
export const profileCatalogs = Object.fromEntries(SUPPORTED_LANGUAGES.map((language,index)=>[
  language,Object.fromEntries(Object.entries(profileTranslationRows).map(([key,values])=>[key,index===0?key:values[index-1]])),
])) as Record<Language,Record<ProfileKey,string>>;
export const profileT = createTranslator(profileCatalogs);

/** Only use with authored content fields; proper names and unknown content pass through. */
export function profileText(language:Language,source:string):string{
  if(language==='en')return source;
  const key=profileKeyByLowerCase.get(source.toLowerCase());
  return key?profileT(language,key):source;
}
const profileKeyByLowerCase = new Map(Object.keys(profileTranslationRows).map(key=>[key.toLowerCase(),key as ProfileKey]));
export function profileBadge(language:Language,source:string):string{
  if(Object.prototype.hasOwnProperty.call(profileTranslationRows,source))return profileText(language,source);
  return source.split(' ').map(part=>profileText(language,part)).join(' ').toUpperCase();
}
export function profileUpgradeSummary(language:Language,model:EquipmentDecisionModel):string{
  const upgrade=model.upgrade;
  if(upgrade.maxed)return profileT(language,'Maximum rank +10');
  const missing = (['gold','dust','cores'] as const).flatMap(key=>{
    const amount=upgrade[key].missing;
    return amount?[amount.toLocaleString(language)+' '+profileT(language,key==='gold'?'Gold':key==='dust'?'Dust':'Cores')]:[];
  });
  const params={rank:upgrade.targetRank,chance:Math.round(upgrade.successChance*100),materials:missing.join(', ')};
  return profileT(language,missing.length?'Next +{rank} · {chance}% · Missing {materials}':'Next +{rank} · {chance}% · Materials ready',params);
}
export function profileRecordValue(language:Language,id:string,value:number):string{
  const unit=personalRecordDefinition(id)?.unit;
  if(unit==='milliseconds'){
    const seconds=value/1000;
    return seconds>=60?Math.floor(seconds/60)+'m '+Math.round(seconds%60)+'s':seconds.toLocaleString(language,{minimumFractionDigits:seconds<10?2:1,maximumFractionDigits:seconds<10?2:1})+'s';
  }
  if(unit==='seconds'){
    const hours=Math.floor(value/3600),minutes=Math.floor(value%3600/60);
    return hours?hours+'h '+minutes+'m':minutes?minutes+'m':Math.floor(value)+'s';
  }
  return Math.floor(value).toLocaleString(language)+(unit==='gold'?' '+profileT(language,'Gold'):unit==='xp'?' XP':'');
}
export function profileError(language:Language,error:unknown,fallback:ProfileKey):string{
  const message=error instanceof Error?error.message:'';
  if(Object.prototype.hasOwnProperty.call(profileTranslationRows,message))return profileText(language,message);
  const missing=/^Missing (.+) in Inventory or Bank$/.exec(message);
  return missing?profileT(language,'Missing {name} in Inventory or Bank',{name:missing[1]}):profileT(language,fallback);
}
/** Adapts only generated unlock-source and set-description fields, never a profile bio/title. */
export function profileSourceText(language:Language,source:string):string{
  const known=profileKeyByLowerCase.get(source.toLowerCase());
  if(known)return profileT(language,known);
  const patterns:ReadonlyArray<readonly [RegExp,ProfileKey,readonly string[]]>=[
    [/^Character level (\d+)$/, 'Character level {level}', ['level']],
    [/^Reach level (\d+) on this character\.$/, 'Reach level {level} on this character.', ['level']],
    [/^Community milestone (\d+)%$/, 'Community milestone {percent}%', ['percent']],
    [/^\+(\d+) DEF and \+(\d+) HP while the full set is equipped\.$/, '+{defense} DEF and +{hp} HP while the full set is equipped.', ['defense','hp']],
    [/^\+(\d+) ATK and \+(\d+) HP while the full set is equipped\.$/, '+{attack} ATK and +{hp} HP while the full set is equipped.', ['attack','hp']],
    [/^\+(\d+) HP and \+(\d+) ATK while the full set is equipped\.$/, '+{hp} HP and +{attack} ATK while the full set is equipped.', ['hp','attack']],
    [/^\+(\d+) ATK while the full set is equipped\.$/, '+{attack} ATK while the full set is equipped.', ['attack']],
  ];
  for(const [pattern,key,names] of patterns){
    const match=pattern.exec(source);
    if(match)return profileT(language,key,Object.fromEntries(names.map((name,index)=>[name,match[index+1]])));
  }
  // Separators belong to authored catalog fragments, including preserved region/event names.
  const parts=source.split(/( · | \/ | — )/);
  return parts.length>1?parts.map((part,index)=>index%2?part:profileSourceText(language,part)).join(''):source;
}


